mapper.select:
SELECT account_id,ingredient_id,base_unit,default_location_id,
       COALESCE(ingredient_name_std,ingredient_name_raw) ingredient_name
  FROM the_full_order.tb_account_ingredient_master WHERE account_id=#{account_id} AND ingredient_id=#{ingredient_id}

mapper.sql:
FROM the_full_order.tb_account_inventory_movement m
LEFT JOIN the_full_order.tb_supplier_ingredient_product p ON p.supplier_product_id=m.supplier_product_id
LEFT JOIN the_full_order.tb_supplier s ON s.supplier_id=p.supplier_id
LEFT JOIN the_full_order.tb_account_ingredient_master ai ON ai.account_id=m.account_id AND ai.ingredient_id=m.ingredient_id
LEFT JOIN the_full_order.tb_ingredient_master im ON im.ingredient_id=m.ingredient_id
WHERE m.account_id=#{account_id}
AND m.ingredient_id=#{ingredient_id}

 AND (COALESCE(m.product_name_snapshot,p.product_name) LIKE CONCAT('%',#{keyword},'%') OR ai.ingredient_name_std LIKE CONCAT('%',#{keyword},'%')
      OR ai.ingredient_name_raw LIKE CONCAT('%',#{keyword},'%') OR im.ingredient_name_std LIKE CONCAT('%',#{keyword},'%')
      OR p.supplier_item_code=#{keyword})

AND m.movement_type IN #{t}
AND m.movement_at>=#{date_from}
AND m.movement_at<DATE_ADD(#{date_to},INTERVAL 1 DAY)
